//! Verity rule-set ABI (Implementation_plan.md §9.1), shared by every rule set.
//!
//! Exports generated by [`export_ruleset!`]:
//!   memory                              (emitted by rustc for cdylib)
//!   alloc(len: i32) -> i32              buffer for the canonical-JSON input
//!   compute(ptr: i32, len: i32) -> i32  pointer to [u32 LE len][canonical JSON output]
//!   trace() -> i32                      pointer to [u32 LE len][NDJSON checkpoints]
//!
//! No imports, no floats, no clock, no randomness: the same bytes come out of
//! wasmtime (provider / verifiers / CLI) and the browser's WebAssembly API.
//!
//! `trace()` is the execution-trace extension (TRACE_V2). Each call to
//! [`checkpoint`] appends one canonical-JSON line `{"state":..,"step":..}` describing
//! an intermediate state. Executors build a Merkle tree over
//! `[input, checkpoint_1 .. checkpoint_n, output]`, so two parties that disagree can
//! find the first divergent step instead of only "the outputs differ".

use std::cell::RefCell;

pub use serde;
pub use serde_json;

use serde::de::DeserializeOwned;
use serde::Serialize;

thread_local! {
    static TRACE: RefCell<Vec<u8>> = const { RefCell::new(Vec::new()) };
}

/// Canonical JSON: sorted keys (serde_json::Map is a BTreeMap without
/// `preserve_order`), compact separators, UTF-8. Byte-identical to Python's
/// `json.dumps(v, sort_keys=True, separators=(",", ":"), ensure_ascii=False)`
/// for the integer/string/bool data rule sets emit.
pub fn canonical<T: Serialize + ?Sized>(value: &T) -> Vec<u8> {
    let v = serde_json::to_value(value).expect("serializable value");
    serde_json::to_vec(&v).expect("json encoding")
}

/// Record one intermediate state of the computation.
pub fn checkpoint<T: Serialize + ?Sized>(step: &str, state: &T) {
    let line = canonical(&serde_json::json!({ "step": step, "state": state }));
    TRACE.with(|t| {
        let mut t = t.borrow_mut();
        t.extend_from_slice(&line);
        t.push(b'\n');
    });
}

/// Leak `bytes` behind a little-endian u32 length prefix and return the pointer.
pub fn envelope(mut bytes: Vec<u8>) -> *const u8 {
    let mut buf = Vec::with_capacity(4 + bytes.len());
    buf.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
    buf.append(&mut bytes);
    let p = buf.as_ptr();
    std::mem::forget(buf);
    p
}

pub fn alloc(len: usize) -> *mut u8 {
    let mut buf: Vec<u8> = Vec::with_capacity(len.max(1));
    let p = buf.as_mut_ptr();
    std::mem::forget(buf);
    p
}

/// Parse input, run the rule, canonicalize the output. Rule errors become a
/// deterministic `{"error": "..."}` output rather than a trap.
pub fn run<I, O>(ptr: *const u8, len: usize, rule: fn(I) -> Result<O, String>) -> *const u8
where
    I: DeserializeOwned,
    O: Serialize,
{
    TRACE.with(|t| t.borrow_mut().clear());
    let slice = if len == 0 { &[][..] } else { unsafe { std::slice::from_raw_parts(ptr, len) } };
    let out = match serde_json::from_slice::<I>(slice) {
        Ok(input) => match rule(input) {
            Ok(output) => canonical(&output),
            Err(e) => {
                checkpoint("error", &e);
                canonical(&serde_json::json!({ "error": e }))
            }
        },
        Err(e) => {
            let msg = format!("invalid input: {e}");
            checkpoint("error", &msg);
            canonical(&serde_json::json!({ "error": msg }))
        }
    };
    envelope(out)
}

pub fn trace_envelope() -> *const u8 {
    envelope(TRACE.with(|t| t.borrow().clone()))
}

/// Round-half-up integer division for non-negative numerators.
pub fn div_round(num: u128, den: u128) -> u128 {
    (num + den / 2) / den
}

/// Round-half-away-from-zero division of a signed value by a positive denominator.
pub fn div_round_i(num: i128, den: i128) -> i128 {
    debug_assert!(den > 0);
    if num >= 0 {
        (num + den / 2) / den
    } else {
        (num - den / 2) / den
    }
}

/// floor(sqrt(n)) by Newton iteration, integers only.
pub fn isqrt(n: u128) -> u128 {
    if n < 2 {
        return n;
    }
    let mut x = n;
    let mut y = (x + 1) / 2;
    while y < x {
        x = y;
        y = (x + n / x) / 2;
    }
    x
}

/// Emit `alloc`, `compute` and `trace` for a rule `fn(Input) -> Result<Output, String>`.
#[macro_export]
macro_rules! export_ruleset {
    ($rule:path) => {
        #[no_mangle]
        pub extern "C" fn alloc(len: usize) -> *mut u8 {
            $crate::alloc(len)
        }

        #[no_mangle]
        pub extern "C" fn compute(ptr: *const u8, len: usize) -> *const u8 {
            $crate::run(ptr, len, $rule)
        }

        #[no_mangle]
        pub extern "C" fn trace() -> *const u8 {
            $crate::trace_envelope()
        }
    };
}
